function shortCard(c){return powerInfo(c).stats}
function cardMarkup(c,{action='',extra=''}={}){if(!c)return '';const power=powerInfo(c);return `<${action?'button':'article'} class="game-card" ${action?`data-action="${action}" data-id="${esc(c.id)}" aria-label="${esc(c.name)}. ${esc(power.action)}. ${esc(power.stats)}"`:''} style="--card:${esc(c.color||'#dfbd83')}"><span class="card-emblem">${cardArt(c)}</span><span class="card-tag">${esc(({Flame:'Ability',Ash:'Light',Wisp:'Companion'}[c.tag])||c.tag||'Light')} POWER${state.run?.lastFlight?.unlockedPowers?.includes(c.id)?'<b class="new-power-badge">NEW</b>':''}</span><h3>${esc(c.name)}</h3><p class="power-action">${icon(power.icon)}<span>${esc(power.action)}</span></p><p class="power-numbers">${esc(power.stats)}</p>${extra}</${action?'button':'article'}>`}
function inspectPower(id){if(screen==='flight')return;const c=cardById(id);if(!c)return;closePower();const power=powerInfo(c),returnFocus=document.activeElement,sheet=document.createElement('dialog');sheet.id='power-inspector';sheet.className='power-sheet';sheet.setAttribute('aria-labelledby','power-sheet-name');sheet.innerHTML=`<div class="power-sheet-title">${cardArt(c)}<h2 id="power-sheet-name">${esc(c.name)}</h2></div><div class="power-sheet-action">${icon(power.icon)}<span>${esc(power.action)}</span></div><p class="power-sheet-stats">${esc(power.stats)}</p>${power.note?`<p class="power-sheet-note">${esc(power.note)}</p>`:''}<div class="power-sheet-duration">${icon('cards')}Automatic · this expedition</div><button class="primary" data-action="close-power">Close</button>`;sheet.addEventListener('close',()=>{sheet.remove();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})},{once:true});document.body.appendChild(sheet);if(typeof sheet.showModal==='function')sheet.showModal();else sheet.setAttribute('open','');sheet.querySelector('button').focus()}
function closePower(){for(const sheet of document.querySelectorAll('#power-inspector,#tuning-inspector')){if(typeof sheet.close==='function'&&sheet.open)sheet.close();else sheet.remove()}}
function renderCards(){const r=state.run,cleared=r.phase==='reward'&&r.current?.type!=='support'&&r.lastFlight?.success;return `<section class="center-view compact-reward ${cleared?'checkpoint-clear':''}">${rewardBanner()}<h1 class="power-choice-title">Choose a power</h1><div class="power-draft-cue">Automatic · this expedition · 3 slots</div>${afterglowPanel()}${discoveryProgress()}<div class="card-offers">${r.offers.map(id=>cardMarkup(cardById(id),{action:'card'})).join('')}</div>${r.cards.length?`<section class="loadout"><div class="loadout-head"><span>${icon('cards')}</span><span>${r.cards.length}/3</span></div>${miniCards(r.cards)}</section>`:''}</section>`}
function renderReplace(){const incoming=cardById(pendingCard),old=cardById(state.run.cards[replaceIndex]);return `<section class="center-view compact-replace"><h1>Replace a power</h1><div class="replace-incoming">${cardArt(incoming)}<div><strong>${esc(incoming.name)}</strong><p>${esc(shortCard(incoming))}</p></div></div><div class="replace-arrow">↓</div><div class="replacement" id="replace-swipe">${cardMarkup(old)}<div class="carousel-dots">${state.run.cards.map((_,i)=>`<i class="carousel-dot ${i===replaceIndex?'active':''}"></i>`).join('')}</div><div class="small subtle">← ${replaceIndex+1}/3 →</div></div><div class="two-actions"><button class="secondary" data-action="keep">Keep ${icon('ember')}+8</button><button class="primary" data-action="replace">Replace ${icon('arrow')}</button></div></section>`}
function bindSwipe(){const e=document.querySelector('#replace-swipe');e.addEventListener('pointerdown',ev=>swipeX=ev.clientX);e.addEventListener('pointerup',ev=>{const dx=ev.clientX-swipeX;if(Math.abs(dx)>30){replaceIndex=(replaceIndex+(dx<0?1:2))%3;render()}})}
function renderSupport(){const r=state.run,n=r.current,choices=getSupportChoices(r,state.profile);const effect=e=>{const bits=[];for(const [key,symbol]of[['flame','flame'],['afterglow','moon'],['embers','ember'],['score','star']])if(e[key])bits.push(`<span class="${e[key]<0?'boon-cost':''}">${icon(symbol)}${key==='flame'&&e[key]>=100?'100':`${e[key]>0?'+':'−'}${Math.abs(e[key])}`}</span>`);if(e.draft)bits.push(`<span>${icon('cards')}1</span>`);return bits.join('')};const names={rest:'Refill',gather:'Gather',spring:'Refill','spring-gold':'Gather',bargain:'Trade','bargain-shield':'Reserve','bargain-safe':'Gather','nest-ward':'Reserve','nest-gold':'Gather','shrine-draft':'New power','shrine-keep':'Gather',well:'Refill','well-gold':'Gather','archive-draft':'New power','archive-rest':'Refill','shrine-fuel':'Refill','shrine-inspiration':'New power','practice-rest':'Refill'};return `<section class="center-view compact-support">${tutorialCheckpoint()}<div class="support-symbol"></div><h1>${esc(n.name)}</h1><div class="support-vitals">${livesMarkup(r)}<span>${icon('flame')}${Math.round(r.flame??100)}</span><span>${icon('ember')}${Math.floor(state.profile.embers||0)}</span></div>${afterglowPanel()}${discoveryProgress()}${tuningEntry({prominent:true})}<div class="support-offers">${choices.map((c,i)=>`<button class="route-choice boon-choice" data-action="support" data-index="${i}" aria-label="${esc(c.title)}. ${esc(c.description)}"><span class="boon-emblem">${icon(c.effect?.draft?'cards':c.effect?.afterglow?'moon':c.effect?.flame?'flame':c.effect?.score?'star':'ember')}</span><h3>${names[c.id]||esc(c.title)}</h3><div class="boon-values">${effect(c.effect||{})}</div></button>`).join('')}</div></section>`}
function modifierText(){const r=state.run,m=getModifiers(r.cards,r.skills||state.profile.skills,r.flightTuning),bits=[];if(Math.abs(m.speed-1)>.01)bits.push(`Travel ${m.speed>1?'+':''}${Math.round((m.speed-1)*100)}%`);if(Math.abs(m.flap-1)>.01)bits.push(`Lift ${m.flap>1?'+':''}${Math.round((m.flap-1)*100)}%`);if(Math.abs(m.gravity-1)>.01)bits.push(`Gravity ${m.gravity>1?'+':''}${Math.round((m.gravity-1)*100)}%`);return bits.join(' · ')||'Balanced flight · familiar controls'}
function renderBriefing(){const r=state.run,n=r.current,t=terrainInfo(n.terrain),location=nodeLocation(n),art={ruins:0,canopy:1,storm:2}[n.terrain]??0,low=(r.flame??100)<(n.elite?70:n.passage==='cavern'?60:35),badge=n.type==='finale'?'FINAL':n.elite?'ELITE':n.passage==='cavern'?'CAVERN':'REFUGE';return `<section class="center-view compact-briefing">${tutorialCheckpoint()}<div class="encounter-art terrain-${esc(n.terrain)} location-art" data-location="${esc(location.id)}" aria-label="${esc(n.locationName||location.name)}">${levelMapPreview(location)}<span class="encounter-badge ${n.elite?'danger':''}">${badge}</span></div><div class="brief-ascent"><b>${esc(currentAscent(n).label)}</b><span>${esc(currentAscent(n).challengeLabel)}</span></div><div class="location-biome">${icon(t.icon)}${esc(t.name)}</div><h1>${esc(n.name)}</h1><div class="brief-stats"><div>${livesMarkup(r)}</div><div>${icon('flame')}<strong>${Math.round(r.flame??100)}</strong></div><div>${icon('wing')}<strong>−${Math.round(7*(n.flameDrain||1))}</strong></div></div><div class="encounter-loot"><span>${icon('wisp')}+${FLAME_TUNING.emberFuel+(n.fuelBonus||0)}</span><span>${icon('ember')}×${Number(n.routeReward||1).toFixed(2)}</span><span>${icon('cards')}${esc((n.draftTheme||'Power').replace(/Flame/g,'Ability').replace(/Ash/g,'Light'))}</span></div><div class="encounter-fuel">${n.fuelCadence<=2?'●●●':n.fuelCadence>=4?'●○○':'●●○'}<span>FUEL</span><span class="encounter-wind" aria-label="${n.tutorialLesson==='glide'?'Calm practice flight':'Occasional localized drafts'}">${icon('wind')}${n.tutorialLesson==='glide'?'CALM':'PUFFS'}</span><span>≈${formatFlightDuration(n.duration||LEVEL_LENGTH.defaultDuration)}</span></div>${low?`<div class="route-readiness low-glow-warning">${icon('flame')} LOW GLOW</div>`:''}<div class="setpiece-preview">${icon(t.icon)}<span>${esc(n.setpiecePreview||location.signature)}</span></div><div class="encounter-challenge">${icon('star')}${esc(n.challenge||'Reach the waylight')}${n.challengeBonus?`<span>+${n.challengeBonus}${icon('ember')}</span>`:''}</div>${afterglowPanel({draw:true})}${discoveryProgress()}${companionAbilityPreview()}<div class="brief-tuning">${tuningEntry()}</div><button class="primary enter-passage" data-action="launch">Enter ${icon('arrow')}</button><section class="loadout">${miniCards(r.cards)}</section><details class="game-help"><summary aria-label="Flight controls and resource rules">?</summary><div>3 lives for the whole ascension. Any hit ends the attempt; retry that level from the start.<br><br>Tap Lift to rise. ${esc(companionAbilityHelp(r.companionRole))} Hold the ability button to pause.<br><br>Draft puffs nudge you only inside their visible area. Fly above or below them; only Swift’s BOOST resists their push.<br><br>Light packets refill Glow. Dark packets dim illumination up to 40%, recovering over 8s; a light packet clears one dimming effect. Dark packets never drain Glow or lives.<br><br>Your companion fetches only good light packets, returns, then rests ${WISP_TUNING.cooldown}s. Power cards trigger automatically for this expedition.<br><br>Progress is saved in this browser.</div></details></section>`}
function renderSkills(){const branches=[{name:'Companion',key:'wisp',icon:'wisp'},{name:'Ability',key:'boost',icon:'flame'},{name:'Afterglow',key:'afterglow',icon:'moon'}],inRun=state.run&&state.run.phase!=='ended',canBuy=canBuyCheckpointSkills(state);const effects={'wisp-light':'Sight +35 per rank','wisp-reach':'Fetch range +25% per rank','wisp-recovery':'Carrier rest −15% per rank','wisp-bounty':'Pickup embers +10%','boost-focus':'Ability recharge −10%','boost-flare':'Ability duration +15%','afterglow-vessel':'Reserve capacity +15 per rank','afterglow-retention':'Spare Glow retained +10 points per rank','afterglow-anchor':'Defeat loss −10 points per rank'};return `<section class="compact-skills"><div class="compact-page-title"><h1>UPGRADES</h1><span>${icon('ember')}${state.profile.embers||0}</span></div><div class="between-runs upgrade-window">${canBuy?(inRun?'APPLIES NEXT FLIGHT':'PERMANENT RANKS'):state.run?.isTutorial?'FINISH PRACTICE FIRST':'FINISH THIS ATTEMPT FIRST'}</div><div class="skill-branches">${branches.map(b=>`<section class="skill-branch"><div class="branch-head">${icon(b.icon)}<h2>${b.name}</h2>${b.key==='afterglow'?`<span class="branch-preview">${getAfterglowRules(state.profile.skills).cap} cap · ${Math.round(getAfterglowRules(state.profile.skills).retention*100)}% kept · ${Math.round(getAfterglowRules(state.profile.skills).failureLoss*100)}% loss</span>`:''}</div>${skillList().filter(s=>s.id.startsWith(b.key)).map(skill=>{const rank=state.profile.skills[skill.id]||0,max=skill.maxRank||1,complete=rank>=max,cost=getSkillCost(state.profile,skill.id),req=skill.requires?Array.isArray(skill.requires)?skill.requires:[skill.requires]:[],locked=req.some(id=>!state.profile.skills[id]);return `<div class="skill-node ${rank?'owned':''}"><div class="skill-node-copy"><h3>${esc(skill.name)}</h3><p>${effects[skill.id]||esc(skill.description)}</p><div class="rank-pips" aria-label="Rank ${rank} of ${max}">${Array.from({length:max},(_,i)=>`<i class="${i<rank?'filled':''}"></i>`).join('')}</div></div>${complete?`<span class="skill-complete">${icon('check')}</span>`:`<button class="${!locked&&canBuy&&state.profile.embers>=cost?'primary':'secondary'}" data-action="buy-skill" data-id="${esc(skill.id)}" aria-label="Upgrade ${esc(skill.name)} for ${cost} embers" ${locked||!canBuy||state.profile.embers<cost?'disabled':''}>${icon('ember')}${cost}</button>`}</div>`}).join('')}</section>`).join('')}</div></section>`}
function renderCodex(){const discovery=getPowerDiscovery(state),unlocked=new Set(discovery.unlocked),cards=cardList().filter(c=>unlocked.has(c.id));return `<section class="compact-page-title"><h1>Grimoire</h1><span>${icon('cards')}${cards.length}/${cardList().length}</span></section>${discoveryProgress()}<div class="codex-grid">${cards.map(c=>cardMarkup(c)).join('')}</div>`}
function renderResult(){const r=state.run,total=runLength(r);return `<section class="center-view compact-result"><div class="result-symbol">${icon(r.success?'sun':'wisp')}</div><h1>${r.isTutorial?(r.success?'First flight complete':'Practice ended'):(r.success?'Refuge reached':'Ascension ended')}</h1>${r.isTutorial?'<div class="practice-result">Practice · your real reserve is safe</div>':''}<div class="result-lives">${livesMarkup(r)}</div><div class="result-stats"><div><strong>${Math.floor(r.securedEmbers||0)}</strong><span>${icon('ember')}${r.isTutorial?'practice':'SAVED'}</span></div><div><strong>${Math.floor(r.score||0)}</strong><span>${icon('star')}</span></div><div><strong>${Math.min(r.isTutorial?2:5,r.stats?.flights||0)}/${r.isTutorial?2:5}</strong><span>${icon('route')}ASCENTS</span></div></div>${!r.isTutorial&&r.success?`<div class="final-clear-saved">FINAL CLEAR · +${Math.floor(r.lastFlight?.securedEmbers||0)} EMBERS SAVED</div>`:''}${r.isTutorial?'':afterglowChange(r.success?r.afterglowTotals:{loss:r.afterglowTotals?.loss})}${afterglowPanel()}${r.success?discoveryCue():''}<div class="result-loadout">${miniCards(r.cards)}</div>${r.isTutorial?`<button class="primary tutorial-play" data-action="begin-regular">Play ${icon('arrow')}</button>`:`<div class="two-actions"><button class="secondary" data-action="skills">Upgrades ${icon('sun')}</button><button class="primary" data-action="begin">Again ${icon('arrow')}</button></div>`}</section>`}
function launch(){if(engine)return;const r=state.run;if(!r||!beginFlightAttempt(r)){goToRun();return}persist();destroyFlight();screen='flight';paused=false;renderHeader();document.body.classList.add('playing');const n=r.current,t=terrainInfo(n.terrain);app.innerHTML=`<section class="flight-shell"><div class="flight-device"><div class="flight-hud"><div><div class="flight-title">${esc(currentAscent(n).label)} · ${esc(n.locationName||nodeLocation(n).name)}</div><div id="flight-lives">${livesMarkup(r)}</div></div><div class="flight-topstats"><span>${icon('ember')}<b id="flight-embers">0</b></span><span>${icon('star')}<b id="flight-score">0</b></span></div></div><div class="flame-hud"><span>${icon('flame')}</span><div id="flame-meter" role="meter" aria-label="Glow" aria-valuemin="0" aria-valuemax="100"><i id="flame-fill"></i></div><b id="flame-value">100</b></div><div class="flight-progress"><i id="flight-progress-bar"></i></div><div class="canvas-wrap"><canvas id="flight-canvas" aria-label="${esc(n.locationName||nodeLocation(n).name)}. ${esc(n.setpiecePreview||nodeLocation(n).signature)}. Wisp playfield. Lift and your companion ability are below on the right."></canvas><div class="flight-event" id="flight-event"></div>${r.isTutorial?'<div class="tutorial-flight-hint" id="tutorial-hint" aria-live="polite"></div>':''}<div class="wisp-hud" id="wisp-hud" aria-label="Carrier ready"><i></i><span id="wisp-status">100</span></div></div><div class="flight-dock"><div class="flight-mobile-cards">${Array.from({length:3},(_,i)=>r.cards[i]?`<span title="${esc(cardById(r.cards[i]).name)}">${cardArt(cardById(r.cards[i]))}</span>`:'<span class="empty">+</span>').join('')}</div>${boostControlMarkup(r.companionRole)}<button class="flight-control flap-control" id="flap-btn" aria-label="Lift upward">${icon('wing')}<span id="flap-label">LIFT −${Math.round(7*(n.flameDrain||1))}</span></button></div><div id="pause-layer"></div></div></section>`;delete document.body.dataset.element;document.body.dataset.companionTint=r.companionTint||'pearl';document.body.dataset.companionRole=normalizeCompanionRole(r.companionRole);const mods=getModifiers(r.cards,r.skills||state.profile.skills,r.flightTuning);engine=new WispFlight({canvas:document.querySelector('#flight-canvas'),terrain:n.terrain,elite:n.elite,seed:`${r.seed}-${n.id}`,duration:n.duration||LEVEL_LENGTH.defaultDuration,challengeId:n.challengeId,challengeTarget:n.challengeTarget,cards:r.cards,skills:r.skills||state.profile.skills,modifiers:mods,node:n,flame:r.flame??100,companionTint:r.companionTint||'pearl',companionRole:normalizeCompanionRole(r.companionRole),onUpdate:updateFlight,onFinish:completeFlight,onPause:p=>{if(p&&!paused){paused=true;showPause()}}});engine.setMuted?.(muted);bindControls();engine.start()}
function updateFlight(s){lastSnapshot=s;const lives=document.querySelector('#flight-lives');if(!lives)return;lives.innerHTML=livesMarkup(state.run);document.querySelector('#flight-embers').textContent=Math.floor(s.embers||0);document.querySelector('#flight-score').textContent=Math.floor(s.score||0);document.querySelector('#flight-progress-bar').style.width=`${Math.min(100,(s.progress||0)*100)}%`;updateBoostControl(document.querySelector('#boost-btn'),s);const spirit=s.wisp;if(spirit){const status=document.querySelector('#wisp-status'),hud=document.querySelector('#wisp-hud');status.textContent=spirit.phase==='cooldown'?`${spirit.cooldown.toFixed(1)}s`:spirit.phase==='outbound'?'FETCH':spirit.phase==='returning'?(spirit.carrying?`+${spirit.cargoValue||1}`:'RETURN'):`R${Math.round(spirit.radius)}`;hud.dataset.phase=spirit.phase;hud.setAttribute('aria-label',`Carrier ${spirit.phase}. ${spirit.phase==='cooldown'?`${spirit.cooldown.toFixed(1)} seconds`: `Range ${Math.round(spirit.radius)}`}`)}const vitality=Math.round(s.flame??100),meter=document.querySelector('#flame-meter');meter.setAttribute('aria-valuenow',String(vitality));document.querySelector('#flame-fill').style.transform=`scaleX(${vitality/100})`;document.querySelector('#flame-value').textContent=vitality;const exhausted=s.canFlap===false;document.querySelector('.flight-device').classList.toggle('low-flame',vitality<=21);document.querySelector('.flight-device').classList.toggle('exhausted',exhausted);const flap=document.querySelector('#flap-btn');flap.setAttribute('aria-disabled',String(exhausted));flap.setAttribute('aria-label',exhausted?'No Glow. Touch a light packet to lift.':`Lift. Costs ${s.flapCost||7} Glow.`);document.querySelector('#flap-label').textContent=exhausted?'GLIDE':`LIFT −${s.flapCost||7}`;document.querySelector('#flight-event').textContent=s.event||(exhausted?'GLOW EMPTY':vitality<=21?'LOW GLOW':'');const tutorial=document.querySelector('#tutorial-hint'),hint=s.tutorialHintState;if(tutorial){tutorial.hidden=!hint;if(hint){const key=`${hint.id}|${hint.title}|${hint.text}`;if(tutorial.dataset.hint!==key){tutorial.dataset.hint=key;tutorial.innerHTML=`<span>${hint.step||1}/${hint.total||1}</span><div><strong>${esc(hint.title)}</strong><p>${esc(hint.text)}</p></div>`}}}}
function completeFlight(result){const current=engine;engine=null;current?.destroy();finishFlight(state.run,result);if(result.success)settleCheckpoint(state);persist();goToRun()}
function bindControls(){const flap=document.querySelector('#flap-btn'),boost=document.querySelector('#boost-btn');flap.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.flap()});boost.addEventListener('click',e=>{if(e.detail===0&&engine&&!paused)engine.activateAbility()});flap.addEventListener('pointerdown',e=>{e.preventDefault();if(engine&&!paused)engine.flap()});boost.addEventListener('pointerdown',e=>{e.preventDefault();boost.setPointerCapture(e.pointerId);boostHeld=false;boostTimer=setTimeout(()=>{boostHeld=true;togglePause()},480)});boost.addEventListener('pointerup',e=>{e.preventDefault();clearTimeout(boostTimer);if(!boostHeld&&engine&&!paused)engine.activateAbility()});boost.addEventListener('pointercancel',()=>clearTimeout(boostTimer));document.querySelector('.canvas-wrap').addEventListener('pointerdown',e=>{e.preventDefault();if(!paused)engine?.flap()})}
function showPause(){const e=document.querySelector('#pause-layer');if(!e)return;e.innerHTML=`<div class="pause-overlay"><h2>Paused</h2><button class="primary" data-action="resume">Resume ${icon('arrow')}</button><button class="secondary" data-action="leave-flight" aria-label="End attempt. Spend one ascension life.">End attempt −1 ${icon('wisp')}</button></div>`}
function togglePause(){if(!engine)return;if(paused){paused=false;document.querySelector('#pause-layer').innerHTML='';engine.resume()}else{paused=true;engine.pause();showPause()}}
function acceptCard(id,slot=null){const r=state.run,accepted=r.phase==='starter'?applyStarter(r,id):takeCard(r,id,slot);if(!accepted)return;const secured=settleCheckpoint(state);pendingCard=null;persist();goToRun();savedNotice(secured)}
function keepBuild(){if(!takeCard(state.run,null))return;const secured=settleCheckpoint(state);persist();goToRun();savedNotice(secured)}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const action=btn.dataset.action,id=btn.dataset.id;switch(action){case'open-tuning':openTuning();break;case'adjust-tuning':adjustTuning(btn.dataset.axis,btn.dataset.delta);break;case'reset-tuning':resetTuning();break;case'inspect-power':inspectPower(id);break;case'inspect-afterglow':inspectAfterglow();break;case'draw-afterglow':{const amount=drawAfterglow(state.run);if(amount){persist();render();notify(`+${amount} Glow`)}}break;case'learn':beginRun(true);break;case'skip-tutorial':skipTutorial();break;case'begin-regular':if(state.run?.isTutorial)state.profile.tutorialComplete=true;beginRun(false,true);break;case'close-power':closePower();break;case'companion-role':state.settings.companionRole=normalizeCompanionRole(id);persist();render();break;case'companion-tint':if(['pearl','amber','lilac'].includes(id)){state.settings.companionTint=id;persist();render()}break;case'home':navigate('home');break;case'play':state.run&&state.run.phase!=='ended'?goToRun():navigate('home');break;case'continue':goToRun();break;case'begin':beginRun();break;case'restart':abandonAscension();beginRun();break;case'skills':openUpgrades();break;case'return-upgrades':returnFromUpgrades();break;case'codex':navigate('codex');break;case'mute':muted=!muted;try{localStorage.setItem('emberwing-muted',String(muted))}catch{}engine?.setMuted?.(muted);renderHeader();notify(muted?'Sound muted':'Sound enabled');break;case'back-route':if(!state.run?.attemptActive&&['briefing','support'].includes(state.run?.phase)){state.run.path.pop();state.run.current=null;state.run.phase='map';persist();goToRun()}else navigate('home');break;case'node':selectNode(state.run,id);persist();goToRun();break;case'card':if(state.run.cards.length>=3){pendingCard=id;replaceIndex=0;screen='replace';render();window.scrollTo({top:0,behavior:'instant'})}else acceptCard(id);break;case'replace':acceptCard(pendingCard,replaceIndex);break;case'keep':keepBuild();break;case'support':if(resolveSupport(state.run,Number(btn.dataset.index),state.profile)){const secured=settleCheckpoint(state);persist();goToRun();savedNotice(secured)}break;case'launch':launch();break;case'buy-skill':if(buyCheckpointSkill(state,id)){persist();const y=window.scrollY;render();window.scrollTo(0,y);notify('UPGRADE SAVED · NEXT FLIGHT')}break;case'resume':togglePause();break;case'leave-flight':engine?.finish(false);break;case'retry-attempt':retryAttempt();break;case'end-ascension':abandonAscension();navigate('result');break}});
document.addEventListener('keydown',e=>{if(screen==='flight'&&engine){if(['Space','ArrowUp','KeyB','ShiftLeft','ShiftRight','Escape'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape')togglePause();else if(!paused&&['Space','ArrowUp'].includes(e.code))engine.flap();else if(!paused&&['KeyB','ShiftLeft','ShiftRight'].includes(e.code))engine.activateAbility()}else if(screen==='replace'&&['ArrowLeft','ArrowRight'].includes(e.code)){replaceIndex=(replaceIndex+(e.code==='ArrowRight'?1:2))%3;render()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('orientationchange',()=>{if(engine&&!paused){paused=true;engine.pause();showPause()}});
window.addEventListener('pagehide',persist);
function renderHeader(){const r=state.run,isHome=screen==='home',back=['briefing','support'].includes(screen)&&!r?.attemptActive,skills=screen==='skills',checkpoint=!['home','flight','skills'].includes(screen);header.innerHTML=`<div class="game-top-left">${isHome||screen==='retry'?`<span class="header-wisp">${icon('wing')}</span>`:`<button class="game-round back-icon" data-action="${skills?'return-upgrades':back?'back-route':'home'}" aria-label="${skills?'Back to journey':back?'Back to map':'Camp'}">${icon('arrow')}</button>`}</div><div class="header-end"><${checkpoint?'button':'span'} class="bank saved-wallet-bank" ${checkpoint?'data-action="skills"':''} aria-label="Saved permanent wallet: ${Math.floor(state.profile.embers||0)} embers${checkpoint?'. Open upgrades.':''}">${icon('ember')}<span>${Math.floor(state.profile.embers||0)}</span><small>SAVED</small></${checkpoint?'button':'span'}><button class="game-round" data-action="mute" aria-label="${muted?'Enable':'Mute'} sound">${icon(muted?'mute':'sound')}</button></div>`}
function renderHome(){const active=state.run&&state.run.phase!=='ended',tint=state.settings.companionTint||'pearl',role=normalizeCompanionRole(state.settings.companionRole);return `<section class="game-splash minimal-home"><div class="splash-scenery"></div><div class="light-hero" role="img" aria-label="A neutral light and its ${esc(getCompanionAbility(role).name)} companion"><i class="light-main-orb"></i><span class="light-companion-orbit"><i class="light-companion-orb"></i></span></div><div class="sparks">${Array.from({length:14},(_,i)=>`<i style="--x:${8+i*6}%;--t:${4+i%5}s;--d:${-i*.6}s"></i>`).join('')}</div><div class="game-title"><h1>WISPBOUND</h1></div><div class="game-home-bottom">${active?'':afterglowPanel({home:true})}<div class="companion-pick"><div class="companion-pick-label"><span>COMPANION</span><small>${active?'NEXT ASCENSION':'CHOOSE AN ABILITY'}</small></div><div class="companion-roles" role="group" aria-label="Companion role${active?' for the next ascension':''}">${Object.values(COMPANION_ABILITIES).map(a=>`<button class="companion-role ${role===a.id?'selected':''}" data-action="companion-role" data-id="${a.id}" aria-pressed="${role===a.id}" aria-label="${a.name}. ${a.label}. ${esc(a.description)}"><i class="role-wisp" aria-hidden="true">${icon(companionRoleIcon(a.id))}</i><span><strong>${a.label}</strong><small>${a.name}</small></span></button>`).join('')}</div><details class="companion-tint-options"><summary><i aria-hidden="true"></i>${tint.toUpperCase()} GLOW <small>COLOR ONLY</small></summary><div class="companion-tints" role="group" aria-label="Cosmetic companion glow${active?' for the next ascension':''}">${['pearl','amber','lilac'].map(color=>`<button data-action="companion-tint" data-id="${color}" class="companion-choice tint-${color} ${tint===color?'selected':''}" aria-pressed="${tint===color}"><i aria-hidden="true"></i><span>${color.toUpperCase()}</span></button>`).join('')}</div></details></div><button class="game-play" data-action="${active?'continue':'begin'}">${icon('wing')}<span>${active?'CONTINUE':'PLAY'}</span>${icon('arrow')}</button><div class="game-menu-tools"><button data-action="skills" aria-label="Permanent upgrades"><span class="menu-medallion map-art-5"></span></button><button data-action="codex" aria-label="Grimoire"><span class="menu-medallion map-art-4"></span></button>${!active?`<button class="learn-button" data-action="learn" aria-label="Replay the practice route">${icon('wing')}<small>Learn</small></button>`:''}${active?`<button data-action="restart" aria-label="End this ascension and start again">${icon('route')}</button>`:''}</div></div></section>`}
function renderMap(){const r=state.run,total=runLength(r);return `<section class="game-map-screen map-v2 minimal-map"><div class="map-status-strip"><span>${icon('route')}${esc(currentAscent().label)}</span>${livesMarkup(r)}<span>${icon('flame')}${Math.round(r.flame??100)}</span></div>${tutorialCheckpoint()}<div class="map-atlas-frame"><div class="game-map-viewport" id="map-viewport"><svg id="journey-map" class="game-world-map" viewBox="0 0 390 ${mapHeight(r)}" role="group" aria-label="Branching map. Tap a glowing node to inspect. Scroll to scout ahead."></svg></div></div><div class="map-build-dock"><div class="map-preparation">${afterglowPanel()}${tuningEntry()}</div>${discoveryProgress()}${miniCards(r.cards)}</div></section>`}
function pixelMapGlyph(kind,x,y){
 const glyphs=[['111111111','110000011','110111011','110101011','110000011','110000011','110000011','111111111'],['000010000','000111000','001111100','000111000','011111110','000111000','111111111','000010000'],['000010000','000111000','001010100','011010110','110010011','111111111','001000100','011111110'],['000111000','001111100','001010100','001111100','001111100','000111000','000010000','001111100'],['000010000','000111000','001101100','011000110','001101100','000111000','000010000','000010000'],['111111111','110111011','110101011','110101011','110101011','110000011','110000011','111111111']];
 const rows=glyphs[kind]||glyphs[0];return `<g shape-rendering="crispEdges" fill="${['#b3ac82','#819378','#9aadb0','#d3a45f','#a99fb7','#b6b9ad'][kind]||'#c4c7a9'}">${rows.map((row,j)=>[...row].map((v,i)=>v==='1'?`<rect x="${x-22+i*5}" y="${y-20+j*5}" width="5" height="5"/>`:'').join('')).join('')}</g>`;
}
function drawMap(){
  const r=state.run,height=mapHeight(r),origin=height-57,svg=document.querySelector('#journey-map');if(!svg)return;
  const choices=getChoices(r),available=new Set(choices.map(n=>n.id)),visited=new Set(r.path),positions={},byId=new Map(r.map.flat().map(n=>[n.id,n]));
  const modern=r.map.some(row=>row.some(n=>Array.isArray(n.nextIds)));
  r.map.forEach((row,i)=>row.forEach((n,j)=>{const lane=modern?(Number.isInteger(n.lane)?n.lane:j):(row.length===2?j*2:1);positions[n.id]={x:[65,195,325][lane]??195,y:height-155-i*145};}));
  const nextNodes=n=>Array.isArray(n.nextIds)?n.nextIds.map(id=>byId.get(id)).filter(Boolean):(r.map[n.row+1]||[]);
  const future=new Set(available),queue=[...choices];while(queue.length){for(const n of nextNodes(queue.shift()))if(!future.has(n.id)){future.add(n.id);queue.push(n);}}
  const takenEdges=new Set(r.path.slice(1).map((id,i)=>`${r.path[i]}|${id}`)),last=r.path.at(-1);
  let paths='',locations='',decorations='',clips='';
  const pathMarkup=(d,taken,open,locked,id)=>`<g class="map-route-line ${taken?'path-taken':open?'path-open':locked?'path-locked':'path-future'}"><path d="${d}" class="route-shadow"/><path id="${id}" d="${d}" class="route-thread"/>${open?`<path d="${d}" class="route-current"/>`:''}</g>`;
  r.map.forEach(row=>row.forEach(a=>{for(const b of nextNodes(a)){const p=positions[a.id],q=positions[b.id];if(!p||!q)continue;const d=`M${p.x} ${p.y-33} C${p.x} ${p.y-79},${q.x} ${q.y+81},${q.x} ${q.y+34}`;paths+=pathMarkup(d,takenEdges.has(`${a.id}|${b.id}`),a.id===last&&available.has(b.id),!future.has(a.id)||!future.has(b.id),`route-${a.id}-${b.id}`);}}));
  const starts=(Array.isArray(r.startNodeIds)?r.startNodeIds:r.map[0].map(n=>n.id)).map(id=>byId.get(id)).filter(Boolean);
  for(const node of starts){const q=positions[node.id],d=`M195 ${origin} C195 ${origin-39},${q.x} ${origin-33},${q.x} ${q.y+34}`;paths+=pathMarkup(d,r.path[0]===node.id,r.path.length===0&&available.has(node.id),r.path.length>0&&r.path[0]!==node.id,`origin-${node.id}`);}
  for(let i=0;i<66;i++){const x=(i*137+41)%390,y=(i*211+73)%height;decorations+=`<circle cx="${x}" cy="${y}" r="${i%5===0?1.6:.7}" fill="#f5dcad" opacity="${.16+(i%4)*.07}"/>`;}
  for(let i=0;i<Math.ceil(runLength(r)*1.3);i++){const x=i%2?320:42,y=170+i*119;decorations+=`<g opacity=".17" transform="translate(${x},${y}) rotate(${i%2?-9:8})"><path d="M-53 8Q-37-12-15-6L8-19 40-7 55 15 26 34-4 47-28 29Z" fill="#323a34"/><path d="M-38 5Q-10-14 33-2" fill="none" stroke="#b8c692" stroke-width="2"/><path d="M-17-8v-29h8v26m20-1v-24h7v27m-42-23q23-23 48 0" fill="none" stroke="#68705d" stroke-width="5"/></g>`;}
  r.map.forEach((row,i)=>row.forEach(n=>{
    const p=positions[n.id],reach=available.has(n.id),taken=visited.has(n.id),bypassed=i<r.step&&!taken,possible=future.has(n.id);
    const art=n.type==='support'?(n.kind==='camp'?3:4):n.type==='finale'?5:({ruins:0,canopy:1,storm:2}[n.terrain]??0);
    const location=n.type==='support'?null:nodeLocation(n),label=n.type==='support'?(n.kind==='camp'?'Sanctuary':n.kind==='shrine'?'Flame shrine':'Moon shrine'):(n.locationName||location.name);
    const route=n.type==='support'?(n.kind==='camp'?'REST':n.kind==='shrine'?'REFILL':'EVENT'):n.type==='finale'?'GATE':({refuge:'REFUGE',cavern:'CAVERN',gauntlet:'ELITE'}[n.routeStyle]||(n.elite?'ELITE TRIAL':'PASSAGE'));
    const clip=`map-clip-${n.id}`;clips+=`<clipPath id="${clip}"><circle cx="${p.x}" cy="${p.y}" r="31.5"/></clipPath>`;
    locations+=`<g class="world-map-node ${reach?'reachable':''} ${taken?'taken':''} ${bypassed?'bypassed':''} ${!possible&&!taken?'unreachable':''}" ${reach?`data-action="node" data-id="${esc(n.id)}" role="button" tabindex="0" aria-label="Inspect ${esc(n.name)}. ${esc(n.setpiecePreview||location?.signature||'')}. ${esc(n.fuelPreview||n.description)}. ${esc(n.reward)}"`:''}>
      ${reach?`<rect x="${p.x-45}" y="${p.y-43}" width="90" height="122" fill="transparent" pointer-events="all"/>`:''}
      <ellipse cx="${p.x}" cy="${p.y+35}" rx="39" ry="10" fill="#05171e" opacity=".5"/>
      ${reach?`<circle class="node-aureole" cx="${p.x}" cy="${p.y}" r="48" fill="url(#nodeRadiance)"/><circle class="node-pulse" cx="${p.x}" cy="${p.y}" r="38" fill="none" stroke="#ffe6ac" stroke-width="1.5"/><circle cx="${p.x}" cy="${p.y}" r="43" fill="none" stroke="#d9be7c" stroke-opacity=".28"/>`:''}
      <circle cx="${p.x}" cy="${p.y}" r="34" fill="#102e34" stroke="${reach||taken?'#e7c17c':'#6b998b'}" stroke-width="${reach?2:1}"/>
      ${location?levelMapGlyph(location,p.x,p.y,46):pixelMapGlyph(art,p.x,p.y)}
      ${taken?`<circle cx="${p.x+24}" cy="${p.y+24}" r="10" fill="#e3ba73" stroke="#193f3b" stroke-width="2"/><path d="m${p.x+19} ${p.y+24} 3 3 7-7" fill="none" stroke="#173b35" stroke-width="1.8"/>`:''}
      ${n.elite?`<path d="m${p.x+25} ${p.y-38} 9 10-9 10-9-10Z" fill="#a5563f" stroke="#f3ce91"/><path d="m${p.x+25} ${p.y-34} 0 7m0 3v1" stroke="#ffe7bd" stroke-width="1.5"/>`:''}
      <text x="${p.x}" y="${p.y+56}" class="map-node-name" text-anchor="middle">${esc(label)}</text><text x="${p.x}" y="${p.y+73}" class="map-node-kind" text-anchor="middle">${n.type!=='support'&&!r.isTutorial?`A${getAscentInfo(n).level} · `:''}${route}</text>
      ${last===n.id?`<g transform="translate(${p.x},${p.y-52})"><path d="M0-7 5 0 0 8-5 0Z" fill="#ffe1a2"/><circle r="11" fill="none" stroke="#e8c37b" stroke-opacity=".35"/></g>`:''}
    </g>`;
  }));
  svg.innerHTML=`<defs><linearGradient id="atlasSky" x2="0" y2="1"><stop stop-color="#102a3b"/><stop offset=".46" stop-color="#173c3e"/><stop offset="1" stop-color="#0b2930"/></linearGradient><radialGradient id="moonRadiance"><stop stop-color="#e9dbac" stop-opacity=".30"/><stop offset=".35" stop-color="#c1d9c0" stop-opacity=".10"/><stop offset="1" stop-color="#a6d8c9" stop-opacity="0"/></radialGradient><radialGradient id="nodeRadiance"><stop stop-color="#f5cd81" stop-opacity=".27"/><stop offset=".63" stop-color="#f5cd81" stop-opacity=".10"/><stop offset="1" stop-color="#f5cd81" stop-opacity="0"/></radialGradient><linearGradient id="mapIsland" x2=".4" y2="1"><stop stop-color="#7f9d85"/><stop offset="1" stop-color="#173544"/></linearGradient><pattern id="atlasContour" width="195" height="220" patternUnits="userSpaceOnUse"><path d="M-30 80Q27 12 107 75T235 72M-30 95Q27 27 107 90T235 87M-30 112Q27 44 107 107T235 104" stroke="#a2bc9d" stroke-opacity=".05" fill="none"/></pattern>${clips}</defs><rect width="390" height="${height}" fill="url(#atlasSky)"/><rect width="390" height="${height}" fill="url(#atlasContour)"/><circle cx="195" cy="90" r="155" fill="url(#moonRadiance)"/><circle cx="195" cy="88" r="26" fill="#e9d8a5" opacity=".72"/><circle cx="205" cy="80" r="24" fill="#193641"/><path d="M24 64Q195 8 366 64M24 ${height-18}Q195 ${height+24} 366 ${height-18}" stroke="#9eae8866" stroke-width="1" fill="none"/>${decorations}${paths}${locations}<g transform="translate(195,${origin})"><circle r="23" fill="url(#nodeRadiance)"/><path d="M0-13C3-5 12-3 9 6 6 17-10 16-10 5-10 1-7-2-4-6-5 1-1 2 0-13Z" fill="#e9be77"/><circle r="24" fill="none" stroke="#b79d6855"/></g><text x="195" y="36" class="map-gate-title" text-anchor="middle">${r.isTutorial?'FIRST LIGHT':'THE HOLLOW GATE'}</text><text x="195" y="${height-17}" class="map-origin-label" text-anchor="middle">EVERY GLOW CHOOSES ITS OWN PATH</text>`;
  const viewport=document.querySelector('#map-viewport'),target=positions[choices[0]?.id];
  if(viewport&&target){const ratio=svg.getBoundingClientRect().width/390;viewport.scrollTop=Math.max(0,target.y*ratio-viewport.clientHeight*.62);}
}

function rewardBanner(){const r=state.run,f=r?.lastFlight;if(r?.phase!=='reward'||r.current?.type==='support'||!f?.success)return '';if(r.isTutorial)return `<div class="level-clear practice-clear">${icon('check')}<span>PRACTICE CLEAR</span></div>${nextAscentCue()}`;const parts=[['PACKETS',f.pickupEmbers??f.embers??0],['CLEAR',f.completionBonus||0],['CHALLENGE',f.challengeBonus||0],['SCORE',f.performanceBonus||0]];return `<div class="level-clear"><div class="clear-heading">${icon('check')}LEVEL CLEAR</div><div class="clear-saved"><strong>+${Math.floor(f.securedEmbers||0)}</strong><span>EMBERS <b>SAVED</b></span></div><div class="clear-breakdown">${parts.map(([label,value])=>`<span><b>${Math.floor(value)}</b><small>${label}</small></span>`).join('')}</div></div>${permanentWallet()}${nextAscentCue()}${afterglowChange(f.afterglow)}${discoveryCue()}`}
function cardArt(c){if(!c)return '';const symbol={'ash-ward':'flame','warm-heart':'flame','glass-phoenix':'ember'}[c.id];if(symbol)return `<span class="illustrated-card-icon power-symbol-art power-symbol-${esc(c.id)}" aria-hidden="true">${icon(symbol)}</span>`;const index=cardList().findIndex(item=>item.id===c.id),col=index%4,row=Math.floor(index/4);return `<span class="illustrated-card-icon" style="background-position:${col*100/3}% ${row*50}%" aria-hidden="true"></span>`}
document.addEventListener('keydown',e=>{const target=e.target.closest?.('.world-map-node[role="button"]');if(target&&['Enter',' '].includes(e.key)){e.preventDefault();selectNode(state.run,target.dataset.id);persist();goToRun()}});
render();
